using Godot;
using System;
using System.Buffers.Binary;
using Settings=Godot.Collections.Dictionary;

public partial class AudioDopplerOperations : RefCounted
{
    public const double SoundSpeed=343;
    public const int HalfTaps=16,Taps=32,Phases=1024,MaxProcessingMsec=60000;
    public const string TimeoutError="Doppler exceeded the 60-second processing budget. Split or bake a shorter region.";
    private static bool Cancelled(RefCounted? job)=>job!=null&&job.Call("is_cancelled").AsBool();
    private static Settings Failure(string message)=>new() {["success"]=false,["error"]=message};
    public double bounded(Settings p,string key,double fallback,double low,double high){if(!p.TryGetValue(key,out var raw)||raw.VariantType is not Variant.Type.Int and not Variant.Type.Float)return fallback;double value=raw.AsDouble();return double.IsFinite(value)?Math.Clamp(value,low,high):fallback;}
