    }
    public Vector2 resample(AudioFloatStageReader reader,double position,double[] table){long basis=(long)Math.Floor(position);int phase=(int)Math.Round((position-basis)*Phases,MidpointRounding.AwayFromZero);if(phase==Phases){basis++;phase=0;}var value=Vector2.Zero;long first=basis-HalfTaps+1;for(int tap=0;tap<Taps;tap++)value+=reader.sample(first+tap)*(float)table[phase*Taps+tap];return value;}
    public Settings failure(string message,AudioFloatStageReader dry,AudioFloatStageReader wet,Godot.FileAccess? output,string outputPath){dry.close();wet.close();if(output!=null){output.Close();DirAccess.RemoveAbsolute(outputPath);}return Failure(message);}
