            while(cursor<outputFrames){if((long)Time.GetTicksMsec()-started>=MaxProcessingMsec)return failure(TimeoutError,dry,wet,output,absoluteOutput);if(Cancelled(job))return failure("Cancelled.",dry,wet,output,absoluteOutput);job?.Call("update",.05+.9*cursor/outputFrames,"Rendering Doppler propagation");int count=(int)Math.Min(256,outputFrames-cursor);var bytes=new byte[count*8];for(int index=0;index<count;index++){long frame=cursor+index;double time=(double)frame/rate;var value=dry.sample(frame)*(float)(1-mix);if(mix>0&&time>=wetStart&&time<=wetEnd){double low=Math.Max(0,time-maxDelay),high=time-closest/SoundSpeed,sourceTime=Math.Clamp(previousSource+previousRatio/rate,low,high),separation=closest,x=0,derivative=1;bool converged=false;for(int iteration=0;iteration<12;iteration++){double eased=Math.Tanh(speed*(sourceTime-passTime)/travel);x=travel*eased;separation=Math.Sqrt(closest*closest+x*x);double radial=x/separation*speed*(1-eased*eased);derivative=1+radial/SoundSpeed;double residual=sourceTime+separation/SoundSpeed-time;if(Math.Abs(residual)<=.001/rate){converged=true;break;}if(residual>0)high=sourceTime;else low=sourceTime;double next=sourceTime-residual/derivative;sourceTime=next>low&&next<high?next:(low+high)*.5;}if(!converged)return failure("Doppler propagation-time inversion did not converge.",dry,wet,output,absoluteOutput);previousSource=sourceTime;previousRatio=1/derivative;var shifted=resample(wet,sourceTime*rate,table);double gain=Mathf.Lerp(1,closest/separation,attenuation),pan=Math.Clamp(direction*width*x/separation,-1,1);shifted*=new Vector2((float)Math.Min(1,1-pan),(float)Math.Min(1,1+pan));value+=shifted*(float)(mix*gain);}if(dry.error.Length>0)return failure(dry.error,dry,wet,output,absoluteOutput);if(wet.error.Length>0)return failure(wet.error,dry,wet,output,absoluteOutput);if(!value.IsFinite())return failure("Non-finite audio produced by Doppler.",dry,wet,output,absoluteOutput);BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(index*8,4),BitConverter.SingleToInt32Bits(value.X));BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(index*8+4,4),BitConverter.SingleToInt32Bits(value.Y));}output.StoreBuffer(bytes);if(output.GetError()!=Error.Ok)return failure("Could not write the complete Doppler stage.",dry,wet,output,absoluteOutput);cursor+=count;}if(Cancelled(job))return failure("Cancelled.",dry,wet,output,absoluteOutput);if((long)Time.GetTicksMsec()-started>=MaxProcessingMsec)return failure(TimeoutError,dry,wet,output,absoluteOutput);output.Flush();if(output.GetError()!=Error.Ok)return failure("Could not flush the Doppler stage.",dry,wet,output,absoluteOutput);if((long)Time.GetTicksMsec()-started>=MaxProcessingMsec)return failure(TimeoutError,dry,wet,output,absoluteOutput);output.Close();dry.close();wet.close();return new Settings {["success"]=true,["error"]="",["frames"]=outputFrames,["duration"]=(double)outputFrames/rate,["sample_rate"]=rate,["channels"]=2,["tail_seconds"]=Math.Ceiling(addedTail*rate)/rate};
        }
        finally{dry.close();wet.close();output?.Dispose();}
    }
}
